using System;
using System.Collections.Generic;
using System.Linq;
abstract record Value {
    public sealed record Integer(long Number) : Value;
    public sealed record BooleanValue(bool Flag) : Value;
    public sealed record StringValue(string Text) : Value;
    public sealed record PairValue(Value First, Value Second) : Value;
    public sealed record ListValue(List<Value> Values) : Value;
    public sealed record Closure(Parameter Parameter, Expr Body, Dictionary<string, Value> Environment) : Value;
    public sealed record Builtin(string Name) : Value;
}
sealed class RuntimeError(Position position, string reason) : Exception(reason) {
    public Position Position {
        get;
    } = position;
    public string Reason {
        get;
    } = reason;
}
sealed class Evaluator {
    public int Calls {
        get;
        set;
    }
    static Value Checked(long value, Position position) {
        if (value is < int.MinValue or > int.MaxValue) throw new RuntimeError(position, "integer overflow");
        return new Value.Integer(value);
    }
    static int Compare(Value a, Value b, Position position) {
        switch (a, b) {
            case (Value.Integer x, Value.Integer y): return x.Number.CompareTo(y.Number);
            case (Value.BooleanValue x, Value.BooleanValue y): return x.Flag.CompareTo(y.Flag);
            case (Value.StringValue x, Value.StringValue y): return string.CompareOrdinal(x.Text, y.Text);
            case (Value.PairValue x, Value.PairValue y): {
                int first = Compare(x.First, y.First, position);
                return first == 0 ? Compare(x.Second, y.Second, position) : first;
            }
            case (Value.ListValue x, Value.ListValue y): for (int i = 0; i < Math.Min(x.Values.Count, y.Values.Count); i++) {
                int order = Compare(x.Values[i], y.Values[i], position);
                if (order != 0) return order;
            } return x.Values.Count.CompareTo(y.Values.Count);
            default: throw new RuntimeError(position, "functional value compared");
        }
    }
    static bool MatchPattern(Pattern pattern, Value value, Dictionary<string, Value> bindings) {
        switch (pattern, value) {
            case (WildPattern, _): return true;
            case (NamePattern p, _): bindings[p.Name] = value;
            return true;
            case (IntPattern p, Value.Integer v): return p.Value == v.Number;
            case (BoolPattern p, Value.BooleanValue v): return p.Value == v.Flag;
            case (StringPattern p, Value.StringValue v): return p.Value == v.Text;
            case (ConsPattern p, Value.ListValue v): return v.Values.Count != 0 && MatchPattern(p.Head, v.Values[0], bindings) && MatchPattern(p.Tail, new Value.ListValue(v.Values.Skip(1).ToList()), bindings);
            case (ListPattern p, Value.ListValue v): if (p.Elements.Count != v.Values.Count) return false;
            for (int i = 0; i < p.Elements.Count; i++) if (!MatchPattern(p.Elements[i], v.Values[i], bindings)) return false;
            return true;
            case (PairPattern p, Value.PairValue v): return MatchPattern(p.First, v.First, bindings) && MatchPattern(p.Second, v.Second, bindings);
            default: return false;
        }
    }
    public (Dictionary<string, Value> Environment, List<Value> Values) Group(Group group, Dictionary<string, Value> environment) {
        if (group.Recursive.HasValue) {
            Dictionary<string, Value> shared = new(environment);
            List<Value> closures = group.Bindings.Select(binding => {
                Lambda function = (Lambda)binding.Expression;
                return (Value)new Value.Closure(function.Parameter, function.Body, shared);
            }).ToList();
            for (int i = 0; i < group.Bindings.Count; i++) shared[group.Bindings[i].Name] = closures[i];
            return (new(shared), closures);
        }
        List<Value> values = group.Bindings.Select(binding => Expression(binding.Expression, environment)).ToList();
        Dictionary<string, Value> result = new(environment);
        for (int i = 0; i < group.Bindings.Count; i++) result[group.Bindings[i].Name] = values[i];
        return (result, values);
    }
    Value Apply(Value function, Value argument, Position position) {
        Calls++;
        if (function is Value.Closure closure) {
            Dictionary<string, Value> inner = new(closure.Environment);
            if (closure.Parameter.Name != null) inner[closure.Parameter.Name] = argument;
            return Expression(closure.Body, inner);
        } if (function is Value.Builtin builtin) return Program.ApplyBuiltin(builtin.Name, argument, position);
        throw new InvalidOperationException();
    }
    public Value Expression(Expr expression, Dictionary<string, Value> environment) {
        switch (expression) {
            case IntExpr e: return new Value.Integer(e.Value);
            case BoolExpr e: return new Value.BooleanValue(e.Value);
            case StringExpr e: return new Value.StringValue(e.Value);
            case NameExpr e: return environment[e.Name];
            case Lambda e: return new Value.Closure(e.Parameter, e.Body, new(environment));
            case Apply e: {
                Value function = Expression(e.Function, environment), argument = Expression(e.Argument, environment);
                return Apply(function, argument, e.Position);
            }
            case Negate e: return Checked(-((Value.Integer)Expression(e.Operand, environment)).Number, e.Position);
            case Binary e: {
                Value left = Expression(e.Left, environment);
                if (e.Op == "&&") return ((Value.BooleanValue)left).Flag ? Expression(e.Right, environment) : new Value.BooleanValue(false);
                if (e.Op == "||") return ((Value.BooleanValue)left).Flag ? new Value.BooleanValue(true) : Expression(e.Right, environment);
                Value right = Expression(e.Right, environment);
                if (e.Op is "+" or "-" or "*" or "/" or "mod") {
                    long a = ((Value.Integer)left).Number, b = ((Value.Integer)right).Number;
                    if (e.Op is "/" or "mod" && b == 0) throw new RuntimeError(e.OperatorPosition, "division by zero");
                    long value = e.Op switch {
                        "+" => a + b, "-" => a - b, "*" => a * b, "/" => a / b, _ => a - b * (a / b)
                    };
                    return Checked(value, e.OperatorPosition);
                }
                if (e.Op == "^") return new Value.StringValue(((Value.StringValue)left).Text + ((Value.StringValue)right).Text);
                if (e.Op == "::") return new Value.ListValue(new[] {
                    left
                }.Concat(((Value.ListValue)right).Values).ToList());
                int order = Compare(left, right, e.OperatorPosition);
                return new Value.BooleanValue(e.Op switch {
                    "=" => order == 0, "<>" => order != 0, "<" => order < 0, ">" => order > 0, "<=" => order <= 0, _ => order >= 0
                });
            }
            case Conditional e: return Expression(((Value.BooleanValue)Expression(e.Condition, environment)).Flag ? e.Yes : e.No, environment);
            case PairExpr e: {
                Value first = Expression(e.First, environment), second = Expression(e.Second, environment);
                return new Value.PairValue(first, second);
            }
            case ListExpr e: return new Value.ListValue(e.Elements.Select(element => Expression(element, environment)).ToList());
            case Match e: {
                Value matched = Expression(e.Value, environment);
                foreach (var (pattern, body) in e.Arms) {
                    Dictionary<string, Value> bindings = new();
                    if (MatchPattern(pattern, matched, bindings)) {
                        Dictionary<string, Value> inner = new(environment);
                        foreach (var (name, value) in bindings) inner[name] = value;
                        return Expression(body, inner);
                    }
                } throw new RuntimeError(e.Position, "match failure");
            }
            case LetIn e: {
                var (inner, _) = Group(e.Group, environment);
                return Expression(e.Body, inner);
            }
            default: throw new InvalidOperationException();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
abstract record TypeErrorKind {
    public sealed record Message(string Text) : TypeErrorKind;
    public sealed record Function(MLType Type) : TypeErrorKind;
    public sealed record Check(MLType Expected, MLType Found, UnifyFailure Failure) : TypeErrorKind;
}
sealed class TypeError(Position position, TypeErrorKind kind) : Exception {
    public Position Position {
        get;
    } = position;
    public TypeErrorKind Kind {
        get;
    } = kind;
}
sealed record Local(string Name, Position Position, Scheme Scheme);
sealed class Inference {
    public Unifier Unifier {
        get;
    } = new();
    public List<Local> Locals {
        get;
    } = new();
    public Dictionary<Position, (MLType Type, List<Pattern> Patterns)> Matches {
        get;
    } = new();
    public void Clear() {
        Locals.Clear();
        Matches.Clear();
    }
    TypeError Message(Position position, string text) => new(position, new TypeErrorKind.Message(text));
    void Check(MLType expected, MLType found, Position position) {
        try {
            Unifier.Unify(expected, found);
        } catch (UnifyFailure failure) {
            throw new TypeError(position, new TypeErrorKind.Check(expected, found, failure));
        }
    }
    public (Dictionary<string, Scheme> Environment, List<Scheme> Schemes) Group(Group group, Dictionary<string, Scheme> environment, bool local) {
        HashSet<string> names = new();
        foreach (Binding binding in group.Bindings) {
            if (!names.Add(binding.Name)) throw Message(binding.Position, $"variable '{binding.Name}' is bound twice in this let");
            if (group.Recursive.HasValue && binding.Expression is not Lambda) throw Message(binding.Position, $"'{binding.Name}' in let rec must be a function");
        }
        Dictionary<string, Scheme> recursive = new(environment);
        List<MLType> types = new();
        if (group.Recursive.HasValue) {
            foreach (Binding binding in group.Bindings) {
                MLType type = Unifier.Fresh();
                recursive[binding.Name] = Scheme.Mono(type);
                types.Add(type);
            } for (int i = 0; i < group.Bindings.Count; i++) {
                Binding binding = group.Bindings[i];
                MLType found = Expression(binding.Expression, recursive);
                Check(types[i], found, binding.Position);
            }
        }
        else foreach (Binding binding in group.Bindings) types.Add(Expression(binding.Expression, environment));
        List<Scheme> schemes = types.Select(type => Unifier.Generalize(type, environment)).ToList();
        Dictionary<string, Scheme> result = new(environment);
        for (int i = 0; i < group.Bindings.Count; i++) {
            Binding binding = group.Bindings[i];
            Scheme scheme = schemes[i];
            result[binding.Name] = scheme;
            if (local) Locals.Add(new(binding.Name, binding.Position, scheme));
        } return (result, schemes);
    }
    public MLType Expression(Expr expression, Dictionary<string, Scheme> environment) {
        switch (expression) {
            case IntExpr: return MLType.Int;
            case BoolExpr: return MLType.Bool;
            case StringExpr: return MLType.String;
            case NameExpr e: {
                if (environment.TryGetValue(e.Name, out Scheme? scheme)) return Unifier.Instantiate(scheme);
                string? candidate = environment.Keys.Select(name => (Distance: Program.EditDistance(e.Name, name), Name: name)).Where(pair => pair.Distance <= 2 && pair.Distance < e.Name.Length).OrderBy(pair => pair.Distance).ThenBy(pair => pair.Name, StringComparer.Ordinal).Select(pair => pair.Name).FirstOrDefault();
                throw Message(e.Position, $"unbound variable '{e.Name}'" + (candidate == null ? "" : $" (did you mean '{candidate}'?)"));
            }
            case Lambda e: {
                MLType argument = Unifier.Fresh();
                Dictionary<string, Scheme> inner = new(environment);
                if (e.Parameter.Name != null) inner[e.Parameter.Name] = Scheme.Mono(argument);
                MLType result = Expression(e.Body, inner);
                return new MLType.Function(argument, result);
            }
            case Apply e: {
                MLType function = Unifier.Resolve(Expression(e.Function, environment)), expected, result;
                if (function is MLType.Variable variable) {
                    expected = Unifier.Fresh();
                    result = Unifier.Fresh();
                    Unifier.Bind(variable.Id, new MLType.Function(expected, result));
                }
                else if (function is MLType.Function f) {
                    expected = f.Argument;
                    result = f.Result;
                } else throw new TypeError(e.Function.Position, new TypeErrorKind.Function(function));
                MLType found = Expression(e.Argument, environment);
                Check(expected, found, e.Argument.Position);
                return result;
            }
            case Binary e: {
                MLType a, b, result;
                switch (e.Op) {
                    case "+": case "-": case "*": case "/": case "mod": a = b = result = MLType.Int;
                    break;
                    case "^": a = b = result = MLType.String;
                    break;
                    case "&&": case "||": a = b = result = MLType.Bool;
                    break;
                    case "::": a = Unifier.Fresh();
                    b = result = new MLType.ListType(a);
                    break;
                    default: a = b = Unifier.Fresh();
                    result = MLType.Bool;
                    break;
                }
                MLType first = Expression(e.Left, environment);
                Check(a, first, e.Left.Position);
                MLType second = Expression(e.Right, environment);
                Check(b, second, e.Right.Position);
                return result;
            }
            case Negate e: {
                MLType found = Expression(e.Operand, environment);
                Check(MLType.Int, found, e.Operand.Position);
                return MLType.Int;
            }
            case Conditional e: {
                MLType found = Expression(e.Condition, environment);
                Check(MLType.Bool, found, e.Condition.Position);
                MLType a = Expression(e.Yes, environment), b = Expression(e.No, environment);
                Check(a, b, e.No.Position);
                return a;
            }
            case PairExpr e: {
                MLType first = Expression(e.First, environment), second = Expression(e.Second, environment);
                return new MLType.PairType(first, second);
            }
            case ListExpr e: {
                MLType type = Unifier.Fresh();
                foreach (Expr element in e.Elements) {
                    MLType found = Expression(element, environment);
                    Check(type, found, element.Position);
                } return new MLType.ListType(type);
            }
            case Match e: {
                MLType type = Expression(e.Value, environment), result = Unifier.Fresh();
                foreach (var (pattern, body) in e.Arms) {
                    Dictionary<string, MLType> bindings = new();
                    MLType found = Pattern(pattern, bindings);
                    Check(type, found, pattern.Position);
                    Dictionary<string, Scheme> inner = new(environment);
                    foreach (var (name, boundType) in bindings) inner[name] = Scheme.Mono(boundType);
                    MLType bodyType = Expression(body, inner);
                    Check(result, bodyType, body.Position);
                }
                Matches[e.Position] = (type, e.Arms.Select(arm => arm.Pattern).ToList());
                return result;
            }
            case LetIn e: {
                var (inner, _) = Group(e.Group, environment, true);
                return Expression(e.Body, inner);
            }
            default: throw new InvalidOperationException();
        }
    }
    MLType Pattern(Pattern pattern, Dictionary<string, MLType> bindings) {
        switch (pattern) {
            case WildPattern: return Unifier.Fresh();
            case NamePattern p: if (bindings.ContainsKey(p.Name)) throw Message(p.Position, $"variable '{p.Name}' is bound twice in this pattern");
            MLType type = Unifier.Fresh();
            bindings[p.Name] = type;
            return type;
            case IntPattern: return MLType.Int;
            case BoolPattern: return MLType.Bool;
            case StringPattern: return MLType.String;
            case ConsPattern p: {
                MLType element = Unifier.Fresh(), head = Pattern(p.Head, bindings);
                Check(element, head, p.Head.Position);
                MLType tail = Pattern(p.Tail, bindings), list = new MLType.ListType(element);
                Check(list, tail, p.Tail.Position);
                return list;
            }
            case ListPattern p: {
                MLType element = Unifier.Fresh();
                foreach (Pattern value in p.Elements) {
                    MLType found = Pattern(value, bindings);
                    Check(element, found, value.Position);
                } return new MLType.ListType(element);
            }
            case PairPattern p: {
                MLType first = Pattern(p.First, bindings), second = Pattern(p.Second, bindings);
                return new MLType.PairType(first, second);
            }
            default: throw new InvalidOperationException();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
readonly record struct Position(int File, int Line, int Column) : IComparable<Position> {
    public int CompareTo(Position other) {
        int order = File.CompareTo(other.File);
        if (order == 0) order = Line.CompareTo(other.Line);
        return order == 0 ? Column.CompareTo(other.Column) : order;
    }
}
sealed record Token(string Kind, string Spelling, string Value, Position Position);
static class Lexer {
    static bool Letter(char c) => c is >= 'A' and <= 'Z' or >= 'a' and <= 'z';
    static bool Digit(char c) => c is >= '0' and <= '9';
    public static List<Token> Lex(string text, int file) {
        List<Position> positions = new();
        int row = 1, column = 1;
        foreach (char c in text) {
            positions.Add(new(file, row, column));
            if (c == '\n') {
                row++;
                column = 1;
            } else column++;
        } positions.Add(new(file, row, column));
        List<Token> tokens = new();
        int i = 0;
        while (i < text.Length) {
            if (text[i] is ' ' or '\n') {
                i++;
                continue;
            } int start = i;
            string kind, value = "";
            if (text.AsSpan(i).StartsWith("(*")) {
                int end = text.IndexOf("*)", i + 2, StringComparison.Ordinal);
                if (end >= 0) {
                    i = end + 2;
                    continue;
                } tokens.Add(new("invalid", text[start..], "unterminated comment", positions[start]));
                break;
            }
            if (Digit(text[i])) {
                i++;
                while (i < text.Length && Digit(text[i])) i++;
                string digits = text[start..i].TrimStart('0');
                if (digits.Length == 0) digits = "0";
                if (long.TryParse(digits, NumberStyles.None, CultureInfo.InvariantCulture, out long n) && n <= int.MaxValue) {
                    kind = "integer";
                    value = n.ToString(CultureInfo.InvariantCulture);
                } else {
                    kind = "invalid";
                    value = "integer literal too large";
                }
            } else if (Letter(text[i]) || text[i] == '_') {
                i++;
                while (i < text.Length && (Letter(text[i]) || Digit(text[i]) || text[i] is '_' or '\'')) i++;
                value = text[start..i];
                kind = new[] {
                    "let", "rec", "and", "in", "fun", "if", "then", "else", "match", "with", "true", "false", "mod", "val"
                }.Contains(value) ? "keyword" : "identifier";
            } else if (text[i] == '\'' && i + 1 < text.Length && text[i + 1] is >= 'a' and <= 'z') {
                i += 2;
                while (i < text.Length && (Letter(text[i]) || Digit(text[i]) || text[i] == '_')) i++;
                kind = "type_variable";
                value = text[start..i];
            } else if (text[i] == '"') {
                i++;
                bool closed = false, valid = true;
                System.Text.StringBuilder decoded = new();
                while (i < text.Length && text[i] != '\n') {
                    if (text[i] == '"') {
                        i++;
                        closed = true;
                        break;
                    }
                    if (text[i] == '\\' && i + 1 < text.Length && text[i + 1] != '\n') {
                        switch (text[i + 1]) {
                            case 'n': decoded.Append('\n');
                            break;
                            case 't': decoded.Append('\t');
                            break;
                            case '\\': decoded.Append('\\');
                            break;
                            case '"': decoded.Append('"');
                            break;
                            default: valid = false;
                            break;
                        } i += 2;
                    }
                    else if (text[i] == '\\') i++;
                    else decoded.Append(text[i++]);
                }
                if (!closed) {
                    kind = "invalid";
                    value = "unterminated string";
                } else if (!valid) {
                    kind = "invalid";
                    value = "invalid escape sequence";
                } else {
                    kind = "string";
                    value = decoded.ToString();
                }
            } else {
                if (i + 1 < text.Length && new[] {
                    ";;", "->", "::", "||", "&&", "<=", ">=", "<>"
                }.Contains(text.Substring(i, 2))) {
                    i += 2;
                    kind = "symbol";
                    value = text[start..i];
                }
                else if (":;=<>+-*/^()[],|".Contains(text[i])) {
                    i++;
                    kind = "symbol";
                    value = text[start..i];
                }
                else {
                    kind = "invalid";
                    value = $"illegal character '{text[i++]}'";
                }
            }
            tokens.Add(new(kind, text[start..i], value, positions[start]));
        }
        tokens.Add(new("eof", "", "", positions[^1]));
        return tokens;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
abstract record Expr(Position Position);
sealed record IntExpr(Position Position, long Value) : Expr(Position);
sealed record BoolExpr(Position Position, bool Value) : Expr(Position);
sealed record StringExpr(Position Position, string Value) : Expr(Position);
sealed record NameExpr(Position Position, string Name) : Expr(Position);
sealed record Lambda(Position Position, Parameter Parameter, Expr Body) : Expr(Position);
